    m = me.memory
    if "side" not in m:
        m["side"] = 1
    side = m["side"]

    b = bearing_to(enemy.x, enemy.y)
    d = distance_to(enemy.x, enemy.y)
    r = hypot(me.x, me.y)

    if b > 80.0 and side == -1:
        side = 1
        m["side"] = 1
    if b < -80.0 and side == 1:
        side = -1
        m["side"] = -1

    if r > 5.4:
        e = bearing_to(0.0, 0.0)
        v = 0.4
    elif d < 1.5:
        e = side * 70.0
        v = -0.4
    elif d > 1.8:
        e = b
        v = 0.7
    else:
        e = b
        v = 0.1

    e = norm(e)

    if abs(e) < 2.0:
        t = 0.0
    elif abs(e) < 20.0:
        t = 0.2
    elif abs(e) < 60.0:
        t = 0.5
    else:
        t = 0.6

    if e < 0.0:
        t = -t

    left = clamp(v - t)
    right = clamp(v + t)
    return (left, right)

